// Two triggers feed this node and they hand over completely different shapes:
//   Webhook      -> { body: { businessUid, trade, text } }
//   Chat Trigger -> { chatInput, sessionId }   (no body at all)
// Reading only body.* is what made chat submissions arrive empty and get knocked back.
const body = $json.body || {};
const fromChat = !$json.body && typeof $json.chatInput === 'string';

const text = String(fromChat ? $json.chatInput : (body.text || '')).trim();

return [{
  json: {
    // Chat is a testing surface with no signed-in business, so it gets an obvious placeholder
    // rather than silently writing to a real business's document.
    businessUid: String(body.businessUid || (fromChat ? 'chat-test' : '')),
    trade: String(body.trade || 'fencing').toLowerCase().trim(),
    text,
    source: fromChat ? 'chat' : 'webhook',
    firebaseProjectId: 'quotemy-ai'
  }
}];

let raw = $json.output !== undefined ? $json.output : $json;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch (e) { raw = null; }
}

if (!raw || typeof raw !== 'object' || typeof raw.approved !== 'boolean') {
  return [{ json: {
    approved: false,
    opening: 'Something went wrong on our end while checking your pricing, so nothing has been saved.',
    whyUpdatesNeeded: '',
    fixes: [{ what: 'Please send your description through again. If it happens twice, get in touch and we will sort it out.', example: null }],
    closing: 'Sorry about that.',
    reviewFailed: true
  } }];
}

return [{ json: {
  approved: raw.approved === true,
  opening: String(raw.opening || ''),
  whyUpdatesNeeded: String(raw.whyUpdatesNeeded || ''),
  fixes: Array.isArray(raw.fixes) ? raw.fixes : [],
  closing: String(raw.closing || ''),
  reviewFailed: false
} }];

const cfg = $('Normalize Input').item.json;
const r = $json;
const fixes = Array.isArray(r.fixes) ? r.fixes : [];

// The agent decides what to say and what to group; code decides layout. Formatting is not a
// judgement call and a model asked for markdown drifts.
const md = [];
if (r.opening) { md.push(r.opening); md.push(''); }

if (r.whyUpdatesNeeded) {
  md.push('## Why these updates are needed');
  md.push('');
  md.push(r.whyUpdatesNeeded);
  md.push('');
}

if (fixes.length) {
  md.push('## What needs fixing');
  md.push('');
  fixes.forEach(f => {
    if (!f || !f.what) return;
    md.push('- ' + f.what);
    if (f.example) md.push('  - e.g. `' + f.example + '`');
  });
  md.push('');
}

if (r.closing) md.push(r.closing);

const report = md.join('\n');

return [{ json: {
  status: 'unverified',
  approved: false,
  businessUid: cfg.businessUid,
  trade: cfg.trade,
  reviewFailed: r.reviewFailed === true,
  report,
  opening: r.opening || '',
  fixes,
  // Kept for the frontend only - a compact list or a count badge. Deliberately not rendered into
  // the report itself: a tradesperson does not need to be told how many things are wrong.
  fixList: fixes.map(f => (f && f.what) || '').filter(Boolean),
  reportWordCount: report.split(/\s+/).filter(Boolean).length
} }];

let raw = $json.output !== undefined ? $json.output : $json;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch (e) { raw = null; }
}

const cfg = $('Normalize Input').item.json;
const rawText = cfg.text.toLowerCase();
const x = (raw && typeof raw === 'object') ? raw : {};

const unmapped = Array.isArray(x.unmapped) ? x.unmapped.slice() : [];

// ---- the canonical vocabulary, mirrored from the output parser schema ----
const MATERIALS = ['timber_pine','timber_hardwood','colorbond','aluminium','pool_aluminium','pool_glass','chainmesh','rural_wire'];
const GATE_TYPES = ['pedestrian_single','driveway_double','driveway_sliding','motor_automation'];
const CONDITIONS = ['sloped','rock','restricted_access','hand_dig'];
const REMOVES = ['timber','metal','any'];
const UNITS = ['per_metre','per_item','per_job','per_sqm'];
const TAGS = ['custom-gates','steep-blocks','pool-compliant','rural-capable','own-installers','insured','glass-capable','automation'];

// ---- gates every value has to pass ----
const quoted = (q) => {
  const s = String(q == null ? '' : q).trim();
  return s ? rawText.includes(s.toLowerCase()) : false;
};
const MAX_RATE = 2000, MAX_PRICE = 100000, MAX_RADIUS = 500, MAX_ENTRIES = 200;
const MIN_HEIGHT = 0.3, MAX_HEIGHT = 4;
const num = (n, max) => typeof n === 'number' && isFinite(n) && n > 0 && n <= max;
const str = (s) => (typeof s === 'string' && s.trim()) ? s.trim() : null;

function take(list, cap) {
  if (!Array.isArray(list)) return [];
  if (list.length > cap) unmapped.push('Only the first ' + cap + ' entries were read from one section - your description may list more than we can store.');
  return list.slice(0, cap);
}

// ---- core rates -> the nested { material: { "1.8m": price } } shape the pricing doc stores ----
const rates = {};
let ratesKept = 0;
for (const r of take(x.rates, MAX_ENTRIES)) {
  if (!r) continue;
  if (!MATERIALS.includes(r.material)) {
    unmapped.push('Could not file a rate under "' + r.material + '" - that is not a fence type we hold, so it was not saved.');
    continue;
  }
  if (!num(r.heightM, MAX_HEIGHT) || r.heightM < MIN_HEIGHT) {
    unmapped.push('Dropped a ' + r.material + ' rate - ' + r.heightM + 'm is not a height we can store.');
    continue;
  }
  if (!num(r.pricePerMetre, MAX_RATE)) {
    unmapped.push('Dropped the ' + r.material + ' ' + r.heightM + 'm rate - ' + r.pricePerMetre + ' per metre is outside the range we accept.');
    continue;
  }
  if (!quoted(r.sourceQuote)) {
    unmapped.push('Dropped the ' + r.material + ' ' + r.heightM + 'm rate - could not find that figure in your description.');
    continue;
  }
  // Key built by code from the number, never taken from model text, so it cannot drift.
  const band = String(r.heightM) + 'm';
  if (!rates[r.material]) rates[r.material] = {};
  rates[r.material][band] = r.pricePerMetre;
  ratesKept += 1;
}

// ---- removals ----
const removals = [];
for (const r of take(x.removals, 20)) {
  if (!r || !REMOVES.includes(r.removes)) continue;
  if (!num(r.pricePerMetre, MAX_RATE) || !quoted(r.sourceQuote)) {
    unmapped.push('Dropped a removal price - could not verify ' + (r && r.pricePerMetre) + ' per metre against your description.');
    continue;
  }
  removals.push({ removes: r.removes, pricePerMetre: r.pricePerMetre });
}

// ---- gates ----
const gates = [];
for (const g of take(x.gates, 30)) {
  if (!g || !GATE_TYPES.includes(g.gateType)) {
    if (g) unmapped.push('Could not file a gate as "' + g.gateType + '" - not a gate type we hold.');
    continue;
  }
  if (!num(g.price, MAX_PRICE) || !quoted(g.sourceQuote)) {
    unmapped.push('Dropped the ' + g.gateType + ' gate price - could not verify it against your description.');
    continue;
  }
  gates.push({
    gateType: g.gateType,
    material: MATERIALS.includes(g.material) ? g.material : null,
    price: g.price,
    isFromPrice: g.isFromPrice === true
  });
}

// ---- site condition surcharges ----
const siteConditions = [];
for (const s of take(x.siteConditions, 20)) {
  if (!s || !CONDITIONS.includes(s.condition)) continue;
  if (!num(s.extraPerMetre, MAX_RATE) || !quoted(s.sourceQuote)) {
    unmapped.push('Dropped the ' + s.condition + ' surcharge - could not verify it against your description.');
    continue;
  }
  siteConditions.push({ condition: s.condition, extraPerMetre: s.extraPerMetre });
}

// ---- other priced add-ons ----
const extras = [];
for (const e of take(x.extras, 30)) {
  if (!e || !str(e.label)) continue;
  const ok = num(e.price, MAX_PRICE) && quoted(e.sourceQuote);
  extras.push({
    label: str(e.label),
    price: ok ? e.price : null,
    unit: UNITS.includes(e.unit) ? e.unit : null,
    isFromPrice: e.isFromPrice === true
  });
  if (e.price != null && !ok) {
    unmapped.push('Kept "' + str(e.label) + '" but not its price - could not verify that figure against your description.');
  }
}

// ---- service area ----
const sa = (x.serviceArea && typeof x.serviceArea === 'object') ? x.serviceArea : {};
const radiusKm = num(sa.radiusKm, MAX_RADIUS) ? sa.radiusKm : null;
if (sa.radiusKm != null && radiusKm === null) {
  unmapped.push('Dropped the travel radius - ' + sa.radiusKm + 'km is outside the range we accept.');
}

// ---- GST ----
let gstIncluded = typeof x.gstIncluded === 'boolean' ? x.gstIncluded : null;
if (gstIncluded !== null && x.gstSourceQuote && !quoted(x.gstSourceQuote)) {
  unmapped.push('Could not confirm the GST wording against your description, so it was left unset.');
  gstIncluded = null;
}

// ---- minimum charge ----
let minimumCharge = num(x.minimumCharge, MAX_PRICE) ? x.minimumCharge : null;
if (x.minimumCharge != null && minimumCharge === null) {
  unmapped.push('Dropped the minimum charge - ' + x.minimumCharge + ' is outside the range we accept.');
} else if (minimumCharge !== null && !quoted(x.minimumChargeSourceQuote)) {
  unmapped.push('Dropped the minimum charge - could not find that figure in your description.');
  minimumCharge = null;
}

const strList = (v, cap) => (Array.isArray(v) ? v : []).map(str).filter(Boolean).slice(0, cap);

// A price list with no surviving core rate is not something to mark verified, even though the review
// step approved it - it would show an empty pricing screen and quote nobody.
const status = ratesKept > 0 ? 'verified' : 'unverified';
if (ratesKept === 0) {
  unmapped.push('No usable rates could be read from your description - please restate your prices and send again.');
}

return [{ json: {
  businessUid: cfg.businessUid,
  trade: cfg.trade,
  status,
  businessName: str(x.businessName),
  gstIncluded,
  enabledMaterials: Object.keys(rates),
  rates,
  removals,
  gates,
  siteConditions,
  serviceArea: {
    baseLocation: str(sa.baseLocation),
    radiusKm,
    excludedAreas: strList(sa.excludedAreas, 40)
  },
  minimumCharge,
  extras,
  inclusions: strList(x.inclusions, 40),
  exclusions: strList(x.exclusions, 40),
  tags: (Array.isArray(x.tags) ? x.tags : []).filter(t => TAGS.includes(t)),
  unmapped,
  ratesKept
} }];

const d = $('Format Extraction').item.json;
const review = $('Read Review Result').item.json;
const verified = d.status === 'verified';

// Enum slugs are how the database stores it; nobody wants to read timber_pine on a summary screen.
const LABELS = {
  timber_pine: 'Treated pine', timber_hardwood: 'Hardwood / merbau', colorbond: 'Colorbond',
  aluminium: 'Aluminium slat', pool_aluminium: 'Pool fencing (aluminium)', pool_glass: 'Pool fencing (glass)',
  chainmesh: 'Chainmesh / security', rural_wire: 'Rural / post and wire',
  pedestrian_single: 'Single pedestrian gate', driveway_double: 'Double driveway gate',
  driveway_sliding: 'Sliding driveway gate', motor_automation: 'Gate motor / automation',
  sloped: 'Sloped or stepped block', rock: 'Rock', restricted_access: 'Restricted access',
  hand_dig: 'Hand dig only', timber: 'Old timber fence', metal: 'Old metal fence', any: 'Existing fence',
  per_metre: 'per metre', per_item: 'each', per_job: 'per job', per_sqm: 'per m2'
};
const label = (k) => LABELS[k] || k;

const md = [];
md.push(verified
  ? (review.opening || 'Your pricing is saved. Have a quick look over the figures below before you confirm.')
  : 'Your pricing came through, but we could not match any of the rates back to what you wrote.');
md.push('');

const rateLines = [];
Object.keys(d.rates).forEach(m => Object.keys(d.rates[m]).forEach(h =>
  rateLines.push('| ' + label(m) + ' | ' + h + ' | $' + d.rates[m][h] + ' |')));
if (rateLines.length) {
  md.push('## Your rates');
  md.push('');
  md.push('| Type | Height | Per metre |');
  md.push('| --- | --- | --- |');
  rateLines.forEach(l => md.push(l));
  md.push('');
}

if (d.removals.length || d.siteConditions.length) {
  md.push('## Removal and site charges');
  md.push('');
  md.push('| | Per metre |');
  md.push('| --- | --- |');
  d.removals.forEach(r => md.push('| ' + label(r.removes) + ' removal | $' + r.pricePerMetre + ' |'));
  d.siteConditions.forEach(s => md.push('| ' + label(s.condition) + ' | + $' + s.extraPerMetre + ' |'));
  md.push('');
}

if (d.gates.length) {
  md.push('## Gates');
  md.push('');
  md.push('| Gate | Price |');
  md.push('| --- | --- |');
  d.gates.forEach(g => md.push('| ' + label(g.gateType) + (g.material ? ' (' + label(g.material) + ')' : '') + ' | ' + (g.isFromPrice ? 'from ' : '') + '$' + g.price + ' |'));
  md.push('');
}

md.push('## Your details');
md.push('');
md.push('| | |');
md.push('| --- | --- |');
md.push('| Area covered | ' + (d.serviceArea.baseLocation ? d.serviceArea.baseLocation + (d.serviceArea.radiusKm ? ', within ' + d.serviceArea.radiusKm + 'km' : '') : 'Not set') + ' |');
if (d.serviceArea.excludedAreas.length) md.push('| Not covered | ' + d.serviceArea.excludedAreas.join(', ') + ' |');
md.push('| Minimum charge | ' + (d.minimumCharge !== null ? '$' + d.minimumCharge : 'Not set') + ' |');
md.push('| GST | ' + (d.gstIncluded === true ? 'Included in the prices above' : d.gstIncluded === false ? 'Not included - added on top' : 'Not set') + ' |');
d.extras.forEach(e => md.push('| ' + e.label + ' | ' + (e.price !== null ? (e.isFromPrice ? 'from ' : '') + '$' + e.price + (e.unit ? ' ' + label(e.unit) : '') : 'Price not set') + ' |'));
md.push('');

if (d.unmapped.length) {
  md.push('## Worth a look');
  md.push('');
  md.push('We could not save these as pricing - either they are not something we hold, or the figure did not match your text.');
  md.push('');
  d.unmapped.forEach(u => md.push('- ' + u));
  md.push('');
}

md.push(verified
  ? 'If a figure looks wrong, update your description and send it again. Confirm on your dashboard to go live.'
  : 'Write your rates out with the number and the unit together, then send it through again.');

const report = md.join('\n');

return [{ json: {
  status: d.status,
  approved: true,
  businessUid: d.businessUid,
  trade: d.trade,
  report,
  pricing: {
    gstIncluded: d.gstIncluded,
    enabledMaterials: d.enabledMaterials,
    rates: d.rates,
    removals: d.removals,
    gates: d.gates,
    siteConditions: d.siteConditions,
    serviceArea: d.serviceArea,
    minimumCharge: d.minimumCharge
  },
  capabilities: {
    businessName: d.businessName,
    tags: d.tags,
    extras: d.extras,
    inclusions: d.inclusions,
    exclusions: d.exclusions
  },
  couldNotUnderstand: d.unmapped,
  ratesSaved: d.ratesKept,
  reportWordCount: report.split(/\s+/).filter(Boolean).length
} }];
